<script setup lang="ts">import{Head,Link,router}from'@inertiajs/vue3';import{reactive}from'vue';import ErpLayout from '@/Layouts/ErpLayout.vue';import type{BranchOption,PaginationMeta,ReconciliationSummary,StatusOption,TreasuryAccountOption}from'@/Types/treasury';defineOptions({layout:ErpLayout});const props=defineProps<{reconciliations:{data:ReconciliationSummary[];meta:PaginationMeta};filters:{search:string;status:string;branch_id:number|null;bank_account_id:number|null;per_page:number};statuses:StatusOption[];branches:BranchOption[];bankAccounts:TreasuryAccountOption[];can:{create:boolean}}>();const filters=reactive({...props.filters});const apply=(page=1):void=>router.get(route('bank-reconciliations.index'),{...filters,page},{preserveState:true,replace:true});const money=(v:string):string=>new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:6}).format(Number(v));</script>
<template><Head title="Bank Reconciliations"/><div class="space-y-6"><div class="flex justify-between"><div><h1 class="text-2xl font-semibold">Bank Reconciliations</h1><p class="mt-1 text-sm text-gray-500">Match statement activity to posted bank ledger transactions.</p></div><Link v-if="can.create" :href="route('bank-reconciliations.create')" class="h-fit rounded-lg bg-brand-500 px-4 py-2.5 text-sm text-white">Start Reconciliation</Link></div><div class="rounded-2xl border bg-white p-5 dark:border-gray-800 dark:bg-gray-900"><div class="grid gap-4 md:grid-cols-5"><input v-model="filters.search" placeholder="Number or statement" class="h-11 rounded-lg border px-3 dark:border-gray-700"/><select v-model="filters.status" class="h-11 rounded-lg border px-3 dark:border-gray-700"><option value="">All statuses</option><option v-for="s in statuses" :key="s.value" :value="s.value">{{s.label}}</option></select><select v-model="filters.branch_id" class="h-11 rounded-lg border px-3 dark:border-gray-700"><option :value="null">All branches</option><option v-for="b in branches" :key="b.id" :value="b.id">{{b.name}}</option></select><select v-model="filters.bank_account_id" class="h-11 rounded-lg border px-3 dark:border-gray-700"><option :value="null">All bank accounts</option><option v-for="a in bankAccounts" :key="a.id" :value="a.id">{{a.code}} — {{a.name}}</option></select><button class="rounded-lg bg-brand-500 text-sm text-white" @click="apply()">Apply</button></div></div><div class="overflow-hidden rounded-2xl border bg-white dark:border-gray-800 dark:bg-gray-900"><div class="overflow-x-auto"><table class="min-w-[1100px] w-full"><thead class="bg-gray-50 dark:bg-white/[.03]"><tr><th class="p-4 text-left text-xs uppercase text-gray-500">Reconciliation</th><th class="p-4 text-left text-xs uppercase text-gray-500">Bank</th><th class="p-4 text-left text-xs uppercase text-gray-500">Period</th><th class="p-4 text-right text-xs uppercase text-gray-500">Statement</th><th class="p-4 text-right text-xs uppercase text-gray-500">Book</th><th class="p-4 text-right text-xs uppercase text-gray-500">Difference</th><th class="p-4 text-left text-xs uppercase text-gray-500">Status</th></tr></thead><tbody class="divide-y dark:divide-gray-800"><tr v-for="r in reconciliations.data" :key="r.id"><td class="p-4"><Link :href="route('bank-reconciliations.show',r.id)" class="font-medium text-brand-600">{{r.reconciliation_number??`Session #${r.id}`}}</Link><p class="text-xs text-gray-500">{{r.statement?.reference}}</p></td><td class="p-4 text-sm">{{r.bank_account?.code}} — {{r.bank_account?.name}}<p class="text-xs text-gray-500">{{r.branch?.name}}</p></td><td class="p-4 text-sm">{{r.statement_start_date}} to {{r.statement_end_date}}</td><td class="p-4 text-right text-sm">{{money(r.statement_closing_balance)}}</td><td class="p-4 text-right text-sm">{{money(r.book_closing_balance)}}</td><td class="p-4 text-right font-semibold" :class="Number(r.difference_amount)!==0?'text-error-600':'text-success-600'">{{money(r.difference_amount)}}</td><td class="p-4"><span class="rounded-full bg-gray-100 px-2.5 py-1 text-xs dark:bg-gray-800">{{r.status_label}}</span></td></tr><tr v-if="reconciliations.data.length===0"><td colspan="7" class="p-12 text-center text-sm text-gray-500">No reconciliation sessions found.</td></tr></tbody></table></div><div class="flex justify-between border-t p-4 text-sm dark:border-gray-800"><span>{{reconciliations.meta.total}} sessions</span><div class="flex gap-2"><button :disabled="reconciliations.meta.current_page<=1" class="rounded border px-3 py-1 disabled:opacity-50" @click="apply(reconciliations.meta.current_page-1)">Previous</button><button :disabled="reconciliations.meta.current_page>=reconciliations.meta.last_page" class="rounded border px-3 py-1 disabled:opacity-50" @click="apply(reconciliations.meta.current_page+1)">Next</button></div></div></div></div></template>
